INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 51, 'theory', 'Quiz: running a service');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 0, 'Why is it better to validate the whole configuration at startup, all at once?', '["It is faster", "The error shows up immediately and clearly, not an hour into running", "The compiler requires it", "It means less code"]', 1, 'The fail-fast principle: wrong settings must not stay hidden until the first time they are used.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 1, 'What should the /ready endpoint check, unlike /health?', '["Only that the process is alive", "The availability of dependencies: the database and so on", "The compiler version", "Nothing"]', 1, '/health does not depend on external systems; /ready answers 503 while the service cannot serve traffic.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 2, 'What is the correct order for a graceful shutdown of a service?', '["Close the pool, then accept requests", "Stop accepting new ones, wait for the current ones, close connections and the pool", "Call exit() right away", "Close only the socket"]', 1, 'This way the requests that are in progress at the moment of the signal are not lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 3, 'Why do we need a timeout for getting a connection from the pool and a timeout for a database query?', '["To make the logs prettier", "So that a failure turns into a fast, clear rejection instead of an endless wait", "To speed up the database", "Docker requires it"]', 1, 'Without bounds on waiting, queues grow and the service "hangs".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 4, 'How can you change the database schema safely, without downtime?', '["Drop the column and deploy the new code right away", "In two steps: expand (compatibly) and only then contract", "Stop all the servers", "Change the schema by hand in the live database"]', 1, 'Old and new instances run at the same time, so you first add, then switch, then remove.');
